/**
 * Experimental continuous eyelid stroke for an imported Rev2D eye rig.
 *
 * This does NOT generate/source new artwork: it replaces the extracted upper
 * and lower eyelash *texture warps* with two thin deformable ribbons following
 * the existing eye-white occlusion mask. The original mask continues to clip
 * the iris, so the eye closes without ghosted translucent drawings or a
 * duplicate lash generated by warping a large raster crop.
 *
 * The vector stroke is intentionally simple and may lose original lash
 * detail. An author must inspect actual frames before accepting it.
 * The workflow is opt-in, provenance-tracked and revokes approval.
 */
import { AvatarWorkflowError } from "./avatar.js";

type UnknownObject = Record<string, unknown>;
type PointArray = number[];

export type VectorEyelidResult = {
  model: UnknownObject;
  newPartIds: string[];
  hiddenPartIds: string[];
  changedOpacityBindings: string[];
  profile: "experimental-vector-eyelids";
};

function unsupported(message: string): never {
  throw new AvatarWorkflowError("VECTOR_EYELIDS_UNSUPPORTED", message);
}
function object(value: unknown): UnknownObject {
  if (!value || typeof value !== "object" || Array.isArray(value)) unsupported("Invalid Rev2D structure");
  return value as UnknownObject;
}
function list(value: unknown): UnknownObject[] {
  if (!Array.isArray(value) || !value.every(v => v && typeof v === "object" && !Array.isArray(v))) {
    unsupported("Missing Rev2D parts or bindings");
  }
  return value as UnknownObject[];
}
function validateColor(color: unknown): string {
  if (typeof color !== "string" || !/^#[0-9a-f]{6}$/i.test(color)) {
    unsupported("Lash color must be a fully opaque #rrggbb value from this avatar");
  }
  return color;
}
function vectorRow(value: unknown): PointArray {
  if (!Array.isArray(value) || value.length < 32 || value.length > 512 ||
      value.length % 4 !== 0 || !value.every(v => typeof v === "number" && Number.isFinite(v))) {
    unsupported("Eye-mask geometry must have two finite rows of 8–128 sampled points");
  }
  return value as number[];
}
function faceRibbon(points: PointArray, row: number, count: number, width: number) {
  const vertices: number[] = [];
  const triangles: number[] = [];
  for (let i = 0; i < count; i++) {
    const x = points[(row * count + i) * 2]!;
    const y = points[(row * count + i) * 2 + 1]!;
    // Thin, tapered stroke: keep the corners anchored to the same position
    // across states instead of scaling an extracted raster texture.
    const weight = Math.sin(Math.PI * i / (count - 1));
    const half = width * (0.12 + 0.88 * Math.sqrt(Math.max(0, weight))) / 2;
    vertices.push(x, y - half, x, y + half);
    if (i < count - 1) {
      const a = 2 * i;
      triangles.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }
  return { vertices, triangles };
}

/**
 * Pure, fail-closed transformation. Valid only for the known single-image
 * Rev2D topology; it refuses rigs with smile eye sprites or foreign eye
 * bindings instead of silently changing an unrelated or artist-authored rig.
 */
export function vectorizeImportedEyelids(
  input: unknown,
  colors: { eyeR: string; eyeL: string },
): VectorEyelidResult {
  const candidate = structuredClone(object(input));
  const parts = list(candidate.parts);
  const bindings = list(candidate.bindings);
  const byPart = new Map<string, UnknownObject>();
  const byBinding = new Map<string, UnknownObject>();
  for (const part of parts) {
    if (typeof part.id !== "string" || byPart.has(part.id)) unsupported("Invalid or duplicate part id");
    byPart.set(part.id, part);
  }
  for (const binding of bindings) {
    if (typeof binding.id !== "string" || byBinding.has(binding.id)) unsupported("Invalid or duplicate binding id");
    byBinding.set(binding.id, binding);
  }
  if ([...byPart.keys()].some(id => id.includes("_vector_") || /^sprite_eyes_smile_/.test(id)) ||
      [...byBinding.keys()].some(id => id.includes("_vector_") || /^sprite_eyes_smile_/.test(id))) {
    unsupported("Already vectorized, or unsupported smiling eye sprite layout");
  }

  const hidden = new Set<string>();
  const modified = new Set<string>();
  const created: string[] = [];
  for (const side of ["eyeR", "eyeL"] as const) {
    const white = byPart.get(side + "_white");
    const upper = byPart.get(side + "_upper");
    const lower = byPart.get(side + "_lower");
    const ball = byPart.get(side + "_ball");
    const mask = byBinding.get(side + "Mask");
    const param = side === "eyeR" ? "EyeROpen" : "EyeLOpen";
    if (!white || !upper || !lower || !ball || !mask ||
        object(white.shape).type !== "mesh" ||
        object(ball.shape).type !== "image" ||
        !Array.isArray(ball.mask) || ball.mask.length !== 1 || ball.mask[0] !== side + "_white" ||
        object(upper.shape).type !== "image" ||
        object(lower.shape).type !== "image" ||
        mask.target !== "part:" + side + "_white.shape.vertices" ||
        !Array.isArray(mask.params) || mask.params.length !== 1 || mask.params[0] !== param) {
      unsupported("Missing or incompatible built-in Rev2D mask / upper / lower eye topology for " + side);
    }
    const maskKeys = list(mask.keys);
    if (maskKeys.length !== 2) unsupported("Eye mask must have exactly open/closed vertex keyforms");
    const closedKey = maskKeys.find(k => Array.isArray(k.at) && k.at.length === 1 && k.at[0] === 0);
    const openedKey = maskKeys.find(k => Array.isArray(k.at) && k.at.length === 1 && k.at[0] === 1);
    if (!closedKey || !openedKey) unsupported("Eye-mask keys must be at EyeOpen=0 and 1");
    const opened = vectorRow(openedKey.value);
    const closed = vectorRow(closedKey.value);
    const count = opened.length / 4;
    if (count !== closed.length / 4 ||
        JSON.stringify(object(white.shape).vertices) !== JSON.stringify(opened)) {
      unsupported("Eye-mask rest vertices must match the open geometry");
    }
    for (let index = 1; index < count; index++) {
      const x = opened[(index * 2)]!;
      const priorX = opened[(index - 1) * 2]!;
      if (x <= priorX) unsupported("Eye mask x positions are not strictly increasing");
    }
    for (let index = 0; index < count; index++) {
      const top = opened[index * 2 + 1]!;
      const bottom = opened[(count + index) * 2 + 1]!;
      const closeTop = closed[index * 2 + 1]!;
      const closeBottom = closed[(count + index) * 2 + 1]!;
      if (bottom + 1e-4 < top || Math.abs(closeTop - closeBottom) > 0.5) {
        unsupported("Eye mask does not converge cleanly at the closed lid line");
      }
    }
    const lash = validateColor(colors[side]);
    for (const [name, row, thickness, z] of [
      ["upper", 0, 2.8, 24.75],
      ["lower", 1, 1.2, 22.8],
    ] as const) {
      const id = side + "_vector_" + name;
      if (byPart.has(id) || byBinding.has(id + "Vertices")) unsupported("Generated vector part id already exists");
      const rest = faceRibbon(opened, row, count, thickness);
      const shut = faceRibbon(closed, row, count, thickness);
      parts.push({
        id, parent: white.parent, z,
        shape: { type: "mesh", ...rest },
        fill: lash,
        description: "Experimental continuous vector lash following eye-mask occlusion; requires visual review",
      });
      bindings.push({
        id: id + "Vertices", target: "part:" + id + ".shape.vertices",
        params: [param],
        keys: [{ at: [0], value: shut.vertices }, { at: [1], value: rest.vertices }],
      });
      created.push(id);
      for (const hiddenId of [side + "_" + name, side + "_" + name + "Rim"]) {
        const part = byPart.get(hiddenId);
        if (!part) continue;
        part.visible = false;
        hidden.add(hiddenId);
      }
    }
  }

  // Rev2D's existing full-eye sprites would cover the new line; hide only
  // these known image variants (not mouth or general purpose expression art).
  for (const [id, part] of byPart) {
    if (/^sprite_eyes_(?:closed|half)_image(?:Left|Right)$/.test(id)) {
      if (object(part.shape).type !== "image") unsupported("Unknown drawn-eye sprite shape");
      part.visible = false;
      hidden.add(id);
    }
  }
  // Restore the underlying eye mask/iris where the now-hidden sprites would
  // previously have disabled it. Reject anything outside this exact topology.
  for (const [id, binding] of byBinding) {
    if (!id.endsWith("UnderSprite")) continue;
    if (!/^eye[LR]_(?:white|ball|lower|upper|lowerRim|crease|upperRim)UnderSprite$/.test(id) ||
        binding.target !== "part:" + id.slice(0, -"UnderSprite".length) + ".opacity") {
      unsupported("Unexpected sprite-hide binding " + id);
    }
    const keys = list(binding.keys);
    for (const key of keys) {
      if (typeof key.value !== "number" || !Number.isFinite(key.value)) unsupported("Invalid eye hide curve");
      key.value = 1;
    }
    modified.add(id);
  }
  return {
    model: candidate, newPartIds: created,
    hiddenPartIds: [...hidden], changedOpacityBindings: [...modified],
    profile: "experimental-vector-eyelids",
  };
}
